<?= $this->extend('frontend/layouts/main') ?><?= $this->section('content') ?><div class="page-hero"><div class="container"><h1>আপনার কার্ট</h1></div></div><div class="container section"><?php if(!$cart['items']): ?><div class="empty-state"><h2>আপনার কার্টে কোনো পণ্য নেই।</h2><a class="btn btn-primary" href="<?= url_to('catalog.products') ?>">পণ্য দেখুন</a></div><?php else: ?><?php foreach($cart['errors'] as $error): ?><div class="alert alert-danger"><?= esc($error) ?></div><?php endforeach ?><div class="row g-4"><div class="col-lg-8"><form method="post" action="<?= url_to('cart.update') ?>"><?= csrf_field() ?><div class="cart-list"><?php foreach($cart['items'] as $item): ?><article class="cart-item"><img src="<?= store_image($item['image']) ?>" width="88" height="88" alt=""><div><h2><?= esc($item['name']) ?></h2><?php if($item['variant_name']): ?><small><?= esc($item['variant_name']) ?></small><?php endif ?><strong><?= format_bdt($item['unit_price']) ?></strong></div><label>পরিমাণ<input class="form-control" type="number" min="1" max="<?= max(1,$item['max']) ?>" name="quantities[<?= esc($item['key'],'attr') ?>]" value="<?= $item['quantity'] ?>"></label><b><?= format_bdt($item['subtotal']) ?></b><button class="btn btn-sm btn-outline-danger" name="key" value="<?= esc($item['key'],'attr') ?>" formaction="<?= url_to('cart.remove') ?>">সরান</button></article><?php endforeach ?></div><button class="btn btn-outline-primary mt-3">কার্ট আপডেট করুন</button></form></div><aside class="col-lg-4"><div class="summary-card"><h2>অর্ডার সারাংশ</h2><div><span>সাবটোটাল</span><strong><?= format_bdt($cart['subtotal']) ?></strong></div><div><span>ডেলিভারি</span><span>চেকআউটে হিসাব হবে</span></div><hr><a class="btn btn-primary btn-lg w-100 <?= $cart['errors']?'disabled':'' ?>" href="<?= url_to('checkout.index') ?>">চেকআউট</a><a class="btn btn-link w-100" href="<?= url_to('catalog.products') ?>">কেনাকাটা চালিয়ে যান</a></div></aside></div><?php endif ?></div><?= $this->endSection() ?>
